/* Seed the Vial EEPROM areas that have no compile-time default (tap dances,
 * combos, macros) with the contents of latest.vil. Runs on a fresh flash and
 * after an EEPROM reset, right after dynamic_keymap_reset() has cleared them. */
#include <string.h>
#include "dynamic_keymap.h"

void eeconfig_init_user(void) {
#ifdef VIAL_TAP_DANCE_ENABLE
    for (size_t i = 0; i < ARRAY_SIZE(vial_default_tap_dances) && i < VIAL_TAP_DANCE_ENTRIES; ++i) {
        vial_tap_dance_entry_t td;
        memcpy_P(&td, &vial_default_tap_dances[i], sizeof(td));
        dynamic_keymap_set_tap_dance(i, &td);
    }
#endif
#ifdef VIAL_COMBO_ENABLE
    for (size_t i = 0; i < ARRAY_SIZE(vial_default_combos) && i < VIAL_COMBO_ENTRIES; ++i) {
        vial_combo_entry_t combo;
        memcpy_P(&combo, &vial_default_combos[i], sizeof(combo));
        dynamic_keymap_set_combo(i, &combo);
    }
#endif
    uint8_t macros[sizeof(vial_default_macro_buffer)];
    memcpy_P(macros, vial_default_macro_buffer, sizeof(macros));
    dynamic_keymap_macro_set_buffer(0, sizeof(macros), macros);
}
